7. let
8.   mkRancherModule =
9.     {
10.       # name used in paths/bin names/etc, e.g. k3s
11.       name,
12.       # systemd service name
13.       serviceName ? name,
14.       # extra flags to pass to the binary before user-defined extraFlags
15.       extraBinFlags ? [ ],
16.       # generate manifests as JSON rather than YAML, see rke2.nix
17.       jsonManifests ? false,
18. 
19.       # which port on the local node hosts content placed in ${staticContentChartDir} on /static/
20.       # if null, it's assumed the content can be accessed via https://%{KUBERNETES_API}%/static/
21.       staticContentPort ? null,
22.     }:
23.     let
24.       cfg = config.services.${name};
25. 
26.       # Paths defined here are passed to the downstream modules as `paths`
27.       manifestDir = "/var/lib/rancher/${name}/server/manifests";
28.       imageDir = "/var/lib/rancher/${name}/agent/images";
29.       containerdConfigTemplateFile = "/var/lib/rancher/${name}/agent/etc/containerd/config.toml.tmpl";
30.       staticContentChartDir = "/var/lib/rancher/${name}/server/static/charts";
31. 
32.       manifestFormat = if jsonManifests then pkgs.formats.json { } else pkgs.formats.yaml { };
33.       # Manifests need a valid suffix to be respected
34.       mkManifestTarget =
35.         name:
36.         if (lib.hasSuffix ".yaml" name || lib.hasSuffix ".yml" name || lib.hasSuffix ".json" name) then
37.           name
38.         else if jsonManifests then
39.           name + ".json"
40.         else
41.           name + ".yaml";
42.       # Returns a path to the final manifest file
43.       mkManifestSource =
44.         name: manifests:
45.         manifestFormat.generate name (
46.           if builtins.isList manifests then
47.             {
48.               apiVersion = "v1";
49.               kind = "List";
50.               items = manifests;
51.             }
52.           else
53.             manifests
54.         );
55. 
56.       # Produces a list containing all duplicate manifest names
57.       duplicateManifests = lib.intersectLists (builtins.attrNames cfg.autoDeployCharts) (
58.         builtins.attrNames cfg.manifests
59.       );
60.       # Produces a list containing all duplicate chart names
61.       duplicateCharts = lib.intersectLists (builtins.attrNames cfg.autoDeployCharts) (
62.         builtins.attrNames cfg.charts
63.       );
64. 
65.       # Converts YAML -> JSON -> Nix
66.       fromYaml =
67.         path:
68.         builtins.fromJSON (
69.           builtins.readFile (
70.             pkgs.runCommand "${path}-converted.json" { nativeBuildInputs = [ pkgs.yq-go ]; } ''
71.               yq --no-colors --output-format json ${path} > $out
72.             ''
73.           )
74.         );
75. 
76.       # Replace prefixes and characters that are problematic in file names
77.       cleanHelmChartName =
78.         name:
79.         let
80.           woPrefix = lib.removePrefix "https://" (lib.removePrefix "oci://" name);
81.         in
82.         lib.replaceStrings
83.           [
84.             "/"
85.             ":"
86.           ]
87.           [
88.             "-"
89.             "-"
90.           ]
91.           woPrefix;
92. 
93.       # Fetch a Helm chart from a public registry. This only supports a basic Helm pull.
94.       fetchHelm =
95.         {
96.           name,
97.           repo,
98.           version,
99.           hash ? lib.fakeHash,
100.         }:
101.         let
102.           isOci = lib.hasPrefix "oci://" repo;
103.           pullCmd = if isOci then repo else "--repo ${repo} ${name}";
104.           name' = if isOci then "${repo}-${version}" else "${repo}-${name}-${version}";
105.         in
106.         pkgs.runCommand (cleanHelmChartName "${name'}.tgz")
107.           {
108.             inherit (lib.fetchers.normalizeHash { } { inherit hash; }) outputHash outputHashAlgo;
109.             impureEnvVars = lib.fetchers.proxyImpureEnvVars;
110.             nativeBuildInputs = with pkgs; [
111.               kubernetes-helm
112.               cacert
113.               # Helm requires HOME to refer to a writable dir
114.               writableTmpDirAsHomeHook
115.             ];
116.           }
117.           ''
118.             helm pull ${pullCmd} --version ${version}
119.             mv ./*.tgz $out
120.           '';
121. 
122.       # Returns the path to a YAML manifest file
123.       mkExtraDeployManifest =
124.         x:
125.         # x is a derivation that provides a YAML file
126.         if lib.isDerivation x then
