141.           valuesContent = builtins.toJSON chartValues;
142.         in
143.         # merge with extraFieldDefinitions to allow setting advanced values and overwrite generated
144.         # values
145.         lib.recursiveUpdate {
146.           apiVersion = "helm.cattle.io/v1";
147.           kind = "HelmChart";
148.           metadata = {
149.             inherit name;
150.             namespace = "kube-system";
151.           };
152.           spec = {
153.             inherit valuesContent;
154.             inherit (value) targetNamespace createNamespace;
155.             chart =
156.               if staticContentPort == null then
157.                 "https://%{KUBERNETES_API}%/static/charts/${name}.tgz"
158.               else
159.                 "https://localhost:${toString staticContentPort}/static/charts/${name}.tgz";
160.             bootstrap = staticContentPort != null; # needed for host network access
161.           };
162.         } value.extraFieldDefinitions;
