1. # profiles/k3s-agent-tiny.nix — k3s agent role for the 1 GB Oracle micro nodes.
2. #
3. # Layers tiny-specific constraints on top of the generic agent profile:
4. #   * --kubelet-arg=max-pods=10 (kubelet defaults to 110, way too many for 1 GB RAM)
5. #   * zramSwap at 50 % so OOMs don't take the node down before workloads
6. #
7. # The "tiny=true:NoSchedule" taint is applied out-of-band with kubectl after
8. # the node first registers — see MAINTENANCE.md "Tiny worker notes".
9. { ... }:
10. {
11.   imports = [ ./k3s-agent.nix ];
12. 
13.   services.k3s.extraFlags = [
14.     "--kubelet-arg=max-pods=10"
15.   ];
16. 
17.   zramSwap = {
18.     enable = true;
19.     algorithm = "zstd";
20.     memoryPercent = 50;
21.   };
22. }
23.

